mapper.select:
SELECT * FROM (
    SELECT * FROM ai_conversation_context
    WHERE session_key = #{sessionKey}
    ORDER BY id DESC
    LIMIT #{limit}
) tmp
ORDER BY id ASC

mapper.delete:
DELETE FROM ai_conversation_context
WHERE session_key = #{sessionKey}
AND id NOT IN (
    SELECT id FROM (
        SELECT id FROM ai_conversation_context
        WHERE session_key = #{sessionKey}
        ORDER BY id DESC
        LIMIT #{keepCount}
    ) tmp
)

DELETE FROM ai_conversation_context
WHERE created_at < #{cutoff}
LIMIT #{batchSize}
